-- 생명주기를 찍는다

@WebServlet(urlPatterns = "/life")
public class LifeServlet extends HttpServlet {

    public LifeServlet() {
        System.out.println("1. 생성자 " + System.identityHashCode(this));
    }

    @Override
    public void init() {
        System.out.println("2. init  " + System.identityHashCode(this));
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        System.out.println("3. doGet " + System.identityHashCode(this)
                + " / " + Thread.currentThread().getName());
        resp.getWriter().write("ok");
    }

    @Override
    public void destroy() {
        System.out.println("4. destroy " + System.identityHashCode(this));
    }
}


