-- 필드를 두면 공유된다

@WebServlet(urlPatterns = "/count", loadOnStartup = 1)
public class CountServlet extends HttpServlet {

    private int count = 0;                 // 위험하다

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        count++;
        resp.getWriter().write(String.valueOf(count));
    }
}

$ for i in $(seq 1 1000); do curl -s localhost:8080/app/count > /dev/null & done
$ wait
$ curl -s localhost:8080/app/count
987

--   천한 번을 불렀는데 987 이다
--   증가가 원자적이지 않다


-- 지역 변수는 안전하다

@WebServlet(urlPatterns = "/safe", loadOnStartup = 1)
public class SafeServlet extends HttpServlet {

    private final AtomicInteger count = new AtomicInteger();

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        int mine = count.incrementAndGet();   // 지역 변수
        resp.getWriter().write(String.valueOf(mine));
    }
}

$ for i in $(seq 1 1000); do curl -s localhost:8080/app/safe > /dev/null & done
$ wait
$ curl -s localhost:8080/app/safe
1001

--   1001 이다
--   ② 4장의 무상태 규칙이 여기서 나왔다


-- 부트도 같다

@RestController
class CountController {
    private int count = 0;

    @GetMapping("/count")
    String count() { return String.valueOf(++count); }
}

$ for i in $(seq 1 1000); do curl -s localhost:8080/count > /dev/null & done
$ wait
$ curl -s localhost:8080/count
993

